SELECT * FROM (SELECT CASE WHEN rating >= 3.5 THEN 'high' WHEN rating >= 1.5 THEN 'mid' ELSE 'low' END AS rating_bucket, ROUND(AVG(rating), 2) AS avg_rating FROM suppliers WHERE city NOT IN ('London', 'Tokyo', 'Singapore') GROUP BY CASE WHEN rating >= 3.5 THEN 'high' WHEN rating >= 1.5 THEN 'mid' ELSE 'low' END) AS s WHERE avg_rating >= 26 ORDER BY avg_rating, rating_bucket LIMIT 3
